head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > loadLocale]<br/>클라이언트 다국어 JS 파일을 동기 방식으로 로드합니다.",
    "validation" : [
        "Url(필수) 파라미터로 로드할 다국어 JS 파일의 URL 을 설정할 수 있어야 합니다.",
        "loadLocale 호출 시 에러가 발생하지 않아야 합니다.",
        "이미 로딩이 완료된 페이지에 새롭게 로드된 다국어 언어팩이 적용되지 않습니다.",
    ]
}



scwin.onpageload = async function () {
    $c.gcm.createCommonDatalist();
    await scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (다국어 적용 버튼)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        localeRef : 'websquare_name',
        useLocale : 'true',
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicButton(cList);
}



scwin.btn_loadLocale_onclick = function () {
    let url = par_Url.getValue();

    // 로드 전 버튼 텍스트
    let beforeText = target1.render.textContent;

    // loadLocale 호출 (에러 발생 여부 확인)
    let error = "없음";
    try {
        WebSquare.util.loadLocale(url);
    } catch (e) {
        error = e.message;
    }

    // 이미 로딩 완료된 페이지의 버튼 텍스트는 변경되지 않음
    let afterText = target1.render.textContent;

    let result = [];
    result.push("에러 : " + error);
    result.push("로드 전 버튼 텍스트 : " + beforeText);
    result.push("로드 후 버튼 텍스트 : " + afterText);
    result.push("기존 페이지 적용 여부 : " + (beforeText === afterText ? "미적용" : "적용됨"));

    wf_body_bottom.getObj("scwin").setReturnValue(result.join("\n"));
}
